import React, { useState, useMemo } from "react";
import ProductCard from "../AllProducts/ProductCard";

const MainProducts = (props) => {
  const [visibleCount, setVisibleCount] = useState(8);

  const visibleProducts = useMemo(() => {
    return (props.product || []).slice(0, visibleCount);
  }, [props.product, visibleCount]);

  if (props.loading) {
    return (
      <div className="flex items-center justify-center h-40">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-kijeka-blue"></div>
      </div>
    );
  }

  const handleLoadMore = () => {
    setVisibleCount(prev => prev + 8);
  };

  return (
    <>
      <div className="flex flex-col p-[10px] pt-0 max-w-full mb-10">
        <div className="grid grid-flow-row grid-cols-1 gap-3 sm:grid-cols-2 md:grid-cols-2 lg:grid-cols-4 w-full">
          {visibleProducts.map((data, index) => {
            if (data[0] !== "") {
              return (
                <ProductCard
                  key={index}
                  index={index}
                  link={data[4]}
                  liked={data[3]}
                  title={data[0]}
                  description={data[1]}
                  img={data[2] ? ((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + data[2]) : ""}
                  rating={data[7]}
                  stars={data[6]}
                />
              );
            } else {
              return null;
            }
          })}
        </div>
        
        {props.product && props.product.length > visibleCount && (
          <div className="flex justify-center mt-8">
            <button 
              onClick={handleLoadMore}
              className="bg-kijeka-blue text-white px-8 py-2 rounded-md hover:bg-opacity-90 transition-all font-medium shadow-md"
            >
              Load More Products
            </button>
          </div>
        )}
      </div>
    </>
  );
};

export default MainProducts;
